-- Textes types du rapport de visite (docs/rapport-de-visite.md), en version générique : modifiables dans les réglages.
INSERT INTO `parametre` (`cle`, `valeur`) VALUES
('textes_rapport', '{
"reunion": "Le maître d''ouvrage a missionné l''AMO pour transmettre le présent compte rendu aux entreprises.",
"pointsGeneraux": "Il est rappelé que le chantier s''effectue sur un site occupé et que toutes les précautions doivent être prises pour limiter les nuisances et prévenir à l''avance de toute période pénalisante (bruit, coupures de réseaux, raccordements techniques…). Les entreprises définissent précisément leurs zones d''intervention et assurent la protection des ouvrages existants.",
"nettoyage": "Chaque entreprise assure le nettoyage de sa zone de travail, enlèvement des gravats compris. À défaut, le maître d''ouvrage pourra faire intervenir une entreprise de nettoyage et poser une benne aux frais de l''entreprise défaillante.",
"sousTraitance": "L''entreprise signataire du devis ne confie pas tout ou partie de ses travaux à un sous-traitant sans l''accord préalable, exprès et écrit du maître d''ouvrage assisté de l''AMO.",
"facturation": "Les factures sont transmises au préalable à l''AMO pour validation, au fur et à mesure de l''avancement. Les travaux supplémentaires ne sont facturables qu''après accord écrit du maître d''ouvrage assisté de l''AMO (avenant validé).",
"plans": "Les plans d''exécution et de réservations sont fournis au préalable au maître d''ouvrage et à l''AMO, dans les plus brefs délais.",
"materiaux": "Les matériaux sont proposés au maître d''ouvrage pour validation avant commande et mise en œuvre.",
"approvisionnements": "Dès que le choix des matériaux est arrêté par le maître d''ouvrage assisté de l''AMO, les entreprises passent commande et informent des délais de livraison.",
"reception": "Les entreprises participent aux réunions de chantier auxquelles elles sont convoquées et lèvent les anomalies constatées avant la réception. Un procès-verbal de réception est établi en fin de chantier, avant facturation du solde des travaux.",
"toutesEntreprises": "Les entreprises se conforment aux plans, devis et détails ainsi qu''aux seuls ordres donnés par le maître d''ouvrage assisté de l''AMO. Les travaux sont exécutés selon les règles de l''art, normes, DTU et avis techniques en vigueur. Il est interdit de fumer à l''intérieur du chantier.",
"securite": "Les entreprises prennent toutes dispositions pour assurer la sécurité du chantier, l''hygiène, la santé et la sécurité de leurs travailleurs. Protections collectives et port des EPI obligatoires.",
"approbation": "Les observations portées sur les rapports de visite ne sont que la confirmation des ordres donnés au cours des visites ou des rendez-vous. Toute observation est à transmettre par e-mail à l''AMO. La date de réception du présent rapport ne peut justifier aucun retard dans la réalisation des travaux."
}'),
('signataire_rapport', '""'),
('agence_rapport', '""'),
('signature_rapport', '""');
